pub trait BookingGateway {
    async fn slots(&self, len: Duration) -> Result<Vec<Slot>, BookingError>;
}

pub struct HttpBookingGateway { client: reqwest::Client, base: Url }

impl BookingGateway for HttpBookingGateway {
    async fn slots(&self, len: Duration) -> Result<Vec<Slot>, BookingError> {
        let raw: ForeignSlots = self.client.get(self.base.join("slots")?)
            .query(&[("minutes", len.as_secs() / 60)])
            .send().await?.error_for_status()?     // transport + HTTP -> BookingError
            .json().await?;
        Ok(raw.into_domestic())                       // foreign -> domestic
    }
}

