pub struct BookingGateway { client: reqwest::blocking::Client, base: String }
impl BookingGateway {
    pub fn slots(&self, len: Duration) -> Result<Vec<Slot>, BookingError> {
        let raw: ForeignSlots = self.client
            .get(format!("{}/slots", self.base))
            .query(&[("minutes", len.as_secs() / 60)])
            .send()?.error_for_status()?.json()?;   // foreign errors wrapped
        Ok(raw.into_domestic())
    }
}
